  ui_story_30980101_36_dialog_content = "Este é o lugar.",
  ui_story_30980101_37_dialog_content = "<color=#e8d9bb>Paramos em frente a um túmulo preto. Um pouco menor do que aqueles ao seu redor. Parecia que o túmulo tinha sido limpo recentemente e tinha rosas brancas novas colocadas nele.</color>",
  ui_story_30980101_38_dialog_content = "Quem era essa?",
