  ui_story_30980101_59_dialog_content = "Eu tenho muitos corpos à minha disposição. Quando um deles fica velho e se aproxima da morte, eu troco de corpo e renasço em um novo.",
  ui_story_30980101_60_dialog_content = "Por isso digo que sou imortal. Eu não conheço o sentimento de morte.",
  ui_story_30980101_61_option_content = "Mas se você não pode morrer... Isso seria uma maldição?",
  ui_story_30980101_62_dialog_content = "Sinto que a maioria das pessoas gostaria de viver pra sempre.",
  ui_story_30980101_63_dialog_content = "É isso que você acha? Talvez você tenha razão.",
  ui_story_30980101_64_option_content = "Imortalidade também pode ser agonizante.",
  ui_story_30980101_65_dialog_content = "Sofrimento? Não conheço esse sentimento também, mas você parece triste agora.",
  ui_story_30980101_66_dialog_content = "Ter que ver as pessoas próximas a você morrendo enquanto você continua vivendo eternamente... deve ser doloroso.",
  ui_story_30980101_67_dialog_content = "Talvez eu tenha sentido essa dor uma vez, mas não me lembro.",
  ui_story_30980101_68_dialog_content = "Outro aspecto da minha imortalidade é que eu não tenho memórias nem emoções.",
  ui_story_30980101_69_dialog_content = "Agora, por exemplo, quando olho para o meu túmulo...",
  ui_story_30980101_70_dialog_content = "Estou procurando na minha mente por alguma memória dessa “Elvia”. Mas não me lembro de nada.",
  ui_story_30980101_71_dialog_content = "Pense mais. Se eu estivesse olhando meu túmulo, eu não reagiria do mesmo jeito que você está agora.",
  ui_story_30980101_72_dialog_content = "Se as coisas são como você diz que são, esse não poderia ser um dos seus corpos “mortos”, né?",
  ui_story_30980101_73_dialog_content = "Eu não lembro...",
  ui_story_30980101_74_dialog_content = "É só, eu acho... Talvez eu tenha sentido a separação de morte uma vez, e talvez... Talvez eu tenha sido próxima e querida no coração de alguém uma vez...",
  ui_story_30980101_75_dialog_content = "Se eu era, quem será que gostava de mim...",
  ui_story_30980101_76_dialog_content = "É provável... que tenha sido ele quem fez esse túmulo pra mim.",
  ui_story_30980101_77_dialog_content = "Agora que você tocou no assunto, parece que esse túmulo é visitado com frequência.",
  ui_story_30980101_78_dialog_content = "Você acha que pode ser ele?",
  ui_story_30980101_79_dialog_content = "Eu... Espero que sim.",
  ui_story_30980101_80_dialog_content = "Desde que descobri essa sepultura, ele sempre volta nessa época para limpar e prestar suas homenagens.",
  ui_story_30980101_81_dialog_content = "Então você já viu essa pessoa?",
  ui_story_30980101_82_dialog_content = "Só de longe, e só de costas. Ele é um homem alto, com cabelo grisalho e orelhas grandes como de uma besta.",
  ui_story_30980101_83_dialog_content = "(Essa descrição soa familiar. Mas quem poderia ser?)",
  ui_story_30980101_84_dialog_content = "Você nunca se aproximou dele pra perguntar sobre seu passado?",
  ui_story_30980101_85_dialog_content = "Eu... Estou com medo... Ou pelo menos acho que é medo. Eu queria muito saber mais sobre mim mesma, mas quando eu penso em perguntar a ele... tenho a sensação de um aperto no meu coração.\nVocê acha que é medo?",
  ui_story_30980101_86_dialog_content = "Eu entendo... Medo é uma resposta natural. Qualquer Aurorian ficaria com medo de encarar o desconhecido.",
  ui_story_30980101_87_dialog_content = "Sou um Aurorian, então?",
  ui_story_30980101_88_dialog_content = "Claro! Por que outro motivo ele viria até sua sepultura em cada ano de aniversário da sua morte?",
  ui_story_30980101_89_dialog_content = "... Por que isso parece tão estranho?",
  ui_story_30980101_90_dialog_content = "Toda vez que ele vem, deixa um buquê de <color=#FFB400>rosas brancas</color>.",
  ui_story_30980101_91_dialog_content = "Ah. Aqui tem rosas brancas.",
  ui_story_30980101_92_dialog_content = "(Rosas brancas... Um símbolo de pureza e inocência? Não, talvez um símbolo de respeito.)",
  ui_story_30980101_93_dialog_content = "Ele deve chegar logo. Eu... Eu quero vê-lo.",
  ui_story_30980101_94_dialog_content = "Mas...",
  ui_story_30980101_95_dialog_content = "Mas... Você devia estar morta! Se eu vir um morto aparecendo na minha frente...",
  ui_story_30980101_96_dialog_content = "Não, espere! Argh, isso é loucura... Não importa o que eu diga, parece que você está morta mesmo.",
  ui_story_30980101_97_dialog_content = "Por isso preciso da sua ajuda.",
  ui_story_30980101_98_option_content = "Sim, eu sei.",
  ui_story_30980101_99_dialog_content = "Você quer que eu pergunte a ele sobre seu passado, certo?",
  ui_story_30980101_100_dialog_content = "Assim está bom pra você?",
  ui_story_30980101_101_option_content = "Ainda não entendi.",
  ui_story_30980101_102_dialog_content = "Eu queria que você perguntasse a ele sobre meu passado no meu lugar.",
  ui_story_30980101_103_dialog_content = "Então é isso...",
  ui_story_30980101_104_dialog_content = "Isso não será um problema.",
  ui_story_30980101_105_dialog_content = "Mas, o seu passado é tão importante assim? Você parece preocupada com isso.",
  ui_story_30980101_106_dialog_content = "Não estou preocupada com meu passado. Mas se eu puder entender as experiências do meu outro eu...",
  ui_story_30980101_107_dialog_content = "O meu eu atual será capaz de pensar como o meu eu anterior?",
  ui_story_30980101_108_dialog_content = "Tenho certeza de que ela era diferente de mim agora... Talvez o coração dela tenha sentido mais coisas do que eu esperaria sentir?",
  ui_story_30980101_109_dialog_content = "...",
  ui_story_30980101_110_option_content = "Mas a expressão do seu rosto me diz que você prefere não saber.",
  ui_story_30980101_111_dialog_content = "Hã?",
  ui_story_30980101_112_dialog_content = "Você parece muito triste. Ou talvez hesitante?",
  ui_story_30980101_113_dialog_content = "Comparado com o eu anterior de que você tá falando, eu acho... O “você” atual é o “você” de verdade.",
  ui_story_30980101_114_dialog_content = "Eu... Estou mesmo com esse tipo de expressão no meu rosto?",
  ui_story_30980101_115_dialog_content = "Eu posso não ser capaz de ler o coração das pessoas, mas posso ler suas expressões com facilidade.",
  ui_story_30980101_116_dialog_content = "Não sei.",
  ui_story_30980101_117_dialog_content = "...",
  ui_story_30980101_118_dialog_content = "Eu não sei se isso é tristeza de verdade ou eu se devo ficar triste nessa situação.",
  ui_story_30980101_119_dialog_content = "Como devo dizer... Para ser sincero, não sei que tipo de influência sua \"maldição\" teve sobre você, Cuscuta...",
  ui_story_30980101_120_dialog_content = "Mas confie sempre no seu coração.",
  ui_story_30980101_121_dialog_content = "Se você descobrir que seu passado não foi muito feliz, o seu futuro não deveria ser mais importante?",
  ui_story_30980101_122_dialog_content = "Meu futuro?",
  ui_story_30980101_123_dialog_content = "Talvez você tenha razão.",
  ui_story_30980101_124_dialog_content = "Ela quase não precisou de nenhuma persuasão, né?",
  ui_story_30980101_125_dialog_content = "Independentemente do que aconteça, no fim, tudo que quero é que você viva uma vida boa. Fico contente desde que você saiba o que é ser feliz.",
  ui_story_30980101_126_dialog_content = "Talvez eu consiga desde que siga você.",
  ui_story_30980101_127_dialog_content = "Hum? Sua expressão... Parece bem melhor agora.",
  ui_story_30980101_128_dialog_content = "Esse é o seu jeito de me chamar pra um encontro?",
  ui_story_30980101_129_dialog_content = "O-o que?!?",
  ui_story_30980101_130_dialog_content = "<color=#e8d9bb>Cuscuta colocou seu buquê de <color=#FFB400>rosas Negras</color> na lápide, ao lado dos brancos.</color>",
  ui_story_30980101_131_dialog_content = "Então vamos seguir em frente...",
  ui_story_30980101_132_dialog_content = "Até o dia em que finalmente nos enterrarem.",
  ui_story_30980601_1_dialog_content = "Você está aqui.",
  ui_story_30980601_2_dialog_content = "Recebi sua mensagem sobre a necessidade de ajuda com algo urgente, então vim o mais rápido que pude.",
  ui_story_30980601_3_dialog_content = "Deve ser algo incrível se alguém tão calmo e sereno como você está pedindo ajuda, Cuscuta.",
  ui_story_30980601_4_dialog_content = "Então, o que exatamente aconteceu? Você está machucado?",
  ui_story_30980601_5_dialog_content = "Estou bem. Estou apenas investigando um caso.",
  ui_story_30980601_6_dialog_content = "Não é de admirar que você esteja vestido de maneira um pouco diferente do normal!",
  ui_story_30980601_7_dialog_content = "Tio Istvan me designou para investigar uma série de assassinatos em série.",
  ui_story_30980601_8_dialog_content = "<size=45>Assassinatos em S-Serial</size>?! Como algo assim aconteceu?",
  ui_story_30980601_9_dialog_content = "Eles foram obra de um notório assassino em série que se esconde nas sombras de Umbraton. Sua onda de violência já tirou a vida de muitas meninas da cidade.",
  ui_story_30980601_10_dialog_content = "Então você está rastreando o assassino? Isso soa terrivelmente perigoso!",
  ui_story_30980601_11_dialog_content = "Apenas uma garota sobreviveu a seu ataque. Ela escapou por pouco da morte ontem e até deu uma olhada no rosto do assassino.",
  ui_story_30980601_12_dialog_content = "Então vocês deveriam protegê-la a todo custo! Já tentou perguntar a ela sobre o assassino?",
  ui_story_30980601_13_dialog_content = "Estamos no meio disso, sim. É apenas...",
  ui_story_30980601_14_dialog_content = "Bem o quê?",
  ui_story_30980601_15_dialog_content = "É também a razão pela qual eu pedi para você vir aqui hoje. Eu esperava que você pudesse me ajudar com minha investigação.",
  ui_story_30980601_16_dialog_content = "Claro! Quanto mais cedo pegarmos aquele maníaco assassino, melhor!",
  ui_story_30980601_17_dialog_content = "Se você não se importa, você poderia...",
  ui_story_30980601_18_dialog_content = "Apenas nomeie, farei qualquer coisa para ajudar!",
  ui_story_30980601_19_dialog_content = "Por favor, vista-se como uma menina.",
  ui_story_30980601_20_dialog_content = "Há? <size=45>AA</size> <size=50>garota</size>?!",
  ui_story_30980601_21_dialog_content = "Isso mesmo.",
  ui_story_30980601_22_option_content = "Vou me trocar agora mesmo!",
  ui_story_30980601_23_dialog_content = "Você concordou tão prontamente... Obrigado, Celestita.",
  ui_story_30980601_24_dialog_content = "Eu preparei um vestido só para você. Aqui.",
  ui_story_30980601_25_dialog_content = "Isso não é nada! Eu sei exatamente por que você precisa de mim para fazer isso.",
  ui_story_30980601_26_option_content = "Eu poderia perguntar por que primeiro?",
  ui_story_30980601_27_dialog_content = "H-Como isso pode ajudar no seu caso?",
  ui_story_30980601_28_dialog_content = "Espera... entendi!",
  ui_story_30980601_29_dialog_content = "Você quer que eu <size=45>fingir</size> ser uma menina, então você pode <size=45>desenhar</size> o assassino e <size=45>capturar</size> ele!",
  ui_story_30980601_30_dialog_content = "Parece um pouco arriscado, mas se isso nos ajudar a pegar o assassino, é um risco que estou disposto a correr!",
  ui_story_30980601_31_dialog_content = "Não é o plano mais infalível que já vi, mas acho que sou a pessoa perfeita para o trabalho... Então vamos lá!",
  ui_story_30980601_32_dialog_content = "Não é isso.",
  ui_story_30980601_33_dialog_content = "Espere o que? Você não precisa de mim para atrair o assassino?",
  ui_story_30980601_34_dialog_content = "O plano que você sugeriu é perfeito, mas ainda não estamos nessa etapa.",
  ui_story_30980601_35_dialog_content = "Hehehe obrigado pelo elogio. Então, qual é exatamente o plano...?",
  ui_story_30980601_36_dialog_content = "Precisamos interrogar o sobrevivente em busca de pistas sobre o assassino.",
  ui_story_30980601_37_dialog_content = "E o que isso tem a ver com eu me vestir de menina?",
  ui_story_30980601_38_dialog_content = "O trauma da sobrevivente a deixou com uma profunda desconfiança em relação aos homens. Eu sou o único com quem ela vai falar agora.",
  ui_story_30980601_39_dialog_content = "Infelizmente, não sou o melhor quando se trata de comunicação e não tenho ideia de como falar com ela.",
  ui_story_30980601_40_dialog_content = "A princípio, pensei que poderia encurtar a distância entre nós simplesmente sentando juntos em silêncio.",
  ui_story_30980601_41_dialog_content = "Talvez seja a aura amaldiçoada que emana do meu corpo, ela parecia ainda mais assustada do que antes.",
  ui_story_30980601_42_dialog_content = "Eu precisava de alguém com habilidades interpessoais impecáveis, alguém que pudesse fazer amizade com qualquer pessoa, e a primeira pessoa em quem pensei foi você.",
  ui_story_30980601_43_dialog_content = "Eu aprecio isso e tudo, mas também não tenho certeza do que dizer a alguém que passou por esse tipo de trauma.",
  ui_story_30980601_44_dialog_content = "...",
  ui_story_30980601_45_dialog_content = "M-Mas ainda farei o meu melhor!",
  ui_story_30980601_46_dialog_content = "Quem tá aí?!",
  ui_story_30980601_47_dialog_content = "Não tenha medo. Sou só eu, Cuscuta.",
  ui_story_30980601_48_dialog_content = "Estou falando daquela pessoa estranha perto de você!",
  ui_story_30980601_49_dialog_content = "(Huh? O que há de tão estranho em mim?! Estou usando este vestido para trás ou algo assim? Eu diria até que estou bonita se você me perguntar.)",
  ui_story_30980601_50_dialog_content = "Este é meu parceiro muito gentil e de bom coração, PlayerName.",
  ui_story_30980601_51_dialog_content = "Oi! Er, aham, olá!",
  ui_story_30980601_52_dialog_content = "você é um cara?",
  ui_story_30980601_53_dialog_content = "Ela viu através de mim! Me desculpe...",
  ui_story_30980601_54_dialog_content = "Por que você está vestido assim? O que você está fazendo?!",
  ui_story_30980601_55_dialog_content = "P-Por favor, não fique nervoso! Só estou usando isso para evitar te incomodar, prometo que não quero fazer mal!",
  ui_story_30980601_56_dialog_content = "Por favor acalme-se.",
  ui_story_30980601_57_dialog_content = "Me desculpe. Eu sei que vocês dois têm boas intenções, é só que meus nervos estão completamente à flor da pele depois de tudo.",
  ui_story_30980601_58_dialog_content = "Imagino que você só encontrará paz se pegarmos o assassino, certo?",
  ui_story_30980601_59_dialog_content = "Isso mesmo! Você tem que pegá-lo logo, não há tempo a perder! Mesmo apenas o pensamento dele é demais...",
  ui_story_30980601_60_dialog_content = "Estamos fazendo todo o possível, mas precisamos da sua ajuda para encontrá-lo...",
  ui_story_30980601_60X1_dialog_content = "Eu sei que relembrar seu trauma é doloroso, mas vai te poupar muito mais sofrimento se você puder nos apontar a direção certa.",
  ui_story_30980601_61_dialog_content = "O-Ok. Lembro-me vagamente dele...",
  ui_story_30980601_62_dialog_content = "Tudo bem, anotamos tudo o que você nos disse.",
  ui_story_30980601_63_dialog_content = "Obrigado por nos fornecer tantas pistas.",
  ui_story_30980601_64_dialog_content = "Por favor, me prometa que você vai pegar aquele monstro!",
  ui_story_30980601_65_dialog_content = "Eu prometo. Não vou deixar você viver sua vida com medo.",
  ui_story_30980601_66_dialog_content = "Obrigado. Estou colocando toda a minha confiança em você.",
  ui_story_30980601_67_dialog_content = "Hum? O que você está olhando?",
  ui_story_30980601_68_dialog_content = "Você parecia um pouco diferente agora, como se entendesse as emoções com mais clareza do que antes.",
  ui_story_30980601_69_dialog_content = "Eu prometo. Não vou deixar você viver sua vida com medo.",
  ui_story_30980601_70_dialog_content = "Você não teria dito algo assim se realmente não tivesse emoções, Cuscuta.",
  ui_story_30980601_71_dialog_content = "Imagino que seja por usar este corpo há tanto tempo que há menos espaços em branco em minhas memórias.",
  ui_story_30980601_72_dialog_content = "No entanto, ainda tenho muito a aprender quando se trata de entender as emoções.",
  ui_story_30980601_73_dialog_content = "Não exija muito de si mesmo, Cuscuta. O fato de você ter sido atencioso o suficiente para confortar aquela garota agora prova que você percorreu um longo caminho.",
  ui_story_30980601_74_dialog_content = "...",
  ui_story_30980601_75_dialog_content = "Com base nas pistas que reunimos, parece que o assassino é um homem jovem e musculoso.",
  ui_story_30980601_76_dialog_content = "A vítima afirma que suas roupas estavam muito manchadas de óleo. Isso, combinado com as pistas que reuni na cidade antes...",
  ui_story_30980601_77_dialog_content = "Significa que ele pode trabalhar na estação de trem.",
  ui_story_30980601_78_dialog_content = "Não temos tempo a perder. Vamos.",
  ui_story_30980601_79_dialog_content = "Espere, algo não parece certo...",
  ui_story_30980601_80_dialog_content = "O assassino sabe que seu rosto foi visto, o que significa que sua identidade provavelmente foi comprometida.",
  ui_story_30980601_81_dialog_content = "Se eu fosse o assassino, definitivamente não voltaria ao meu trabalho.",
