  ui_story_30980601_92_dialog_content = "Quem é você, e o que está fazendo aqui?",
  ui_story_30980601_93_dialog_content = "Eu deveria estar te fazendo a mesma pergunta! Qual é a grande ideia, me atacando do nada assim?!",
  ui_story_30980601_94_dialog_content = "Você está circulando pela mesma área há algum tempo. Por que?",
  ui_story_30980601_95_dialog_content = "Estou perdida, só isso! Eu estava indo para First Street procurar um amigo meu, e alguém me indicou essa direção.",
  ui_story_30980601_95X1_dialog_content = "Mas quando cheguei aqui, notei que todos os sinais de trânsito diziam Second Street! Eu tenho andado por aí tentando encontrar meu caminho desde então.",
  ui_story_30980601_96_dialog_content = "É mesmo?",
  ui_story_30980601_97_dialog_content = "Isso é! Olha, eu tenho o endereço do meu amigo aqui!",
