  ui_story_30980601_99_dialog_content = "Oh não! Nós <size=45>caiu nessa</size>!",
  ui_story_30980601_100_dialog_content = "Ah!",
  ui_story_30980601_101_dialog_content = "Aí está você! Sabíamos que você apareceria mais cedo ou mais tarde, <size=45>assassino em série</size>!",
  ui_story_30980601_102_dialog_content = "Hunf...",
  ui_story_30980601_103_dialog_content = "Mantenha suas mãos longe dela!",
  ui_story_30980601_104_dialog_content = "Urgh—",
  ui_story_30980601_105_dialog_content = "<size=45>Cuscuta</size>!!!",
  ui_story_30980601_106_dialog_content = "Ela não está respirando! O que aconteceu?!",
