  ui_story_30980601_108_dialog_content = "Você <size=45>morto</size> Cuscuta!!!",
  ui_story_30980601_109_dialog_content = "Bwahahaha! E o próximo da fila é <size=45>você</size>!",
  ui_story_30980601_110_dialog_content = "<color=#e8d9bb>Que droga!</color>",
  ui_story_30980601_111_dialog_content = "Argh! Como ousa me bater?!",
  ui_story_30980601_112_dialog_content = "(Esse cara é muito forte. Não vou conseguir aguentar por muito tempo! Preciso pensar em algo...)",
  ui_story_30980601_113_dialog_content = "Aaaaah! Isso dói!!!",
  ui_story_30980601_114_dialog_content = "(Hein? O que está acontecendo com ele?)",
  ui_story_30980601_115_dialog_content = "Aghhhh!",
