  ui_story_30980601_124_dialog_content = "Ufa... Graças a Deus ela acabou de desmaiar. Pelo menos um deles ainda está respirando.",
  ui_story_30980601_125_dialog_content = "Preciso pedir ajuda e mandá-la para o hospital.",
  ui_story_30980601_126_dialog_content = "<size=45>Cuscuta!</size>",
