  ui_story_30980601_128_dialog_content = "Você é <size=45>vivo de novo</size>! Estou tão aliviada!",
  ui_story_30980601_129_dialog_content = "Tá bom.",
  ui_story_30980601_130_dialog_content = "Você parece um pouco fora, Cuscuta. Parece que está faltando alguma coisa...",
  ui_story_30980601_131_dialog_content = "Perco uma parte das minhas memórias sempre que morro e volto à vida. Tudo o que me lembro é que tenho uma missão a cumprir.",
  ui_story_30980601_131X1_dialog_content = "Por isso vim aqui sem perceber.",
  ui_story_30980601_132_dialog_content = "Mas você completou sua missão, Cuscuta!",
