  ui_story_30980601_147_dialog_content = "Isso significa que você pode compreender o que significa <size=45>sacrificar-se por outras pessoas</size>. Essa é uma das emoções mais poderosas que uma pessoa pode sentir!",
  ui_story_30980601_148_dialog_content = "Certo.",
